    case DEHERM_RECORDING_SHAPE_UNDEFINED: return expectTag(ScriptValueTag::kUndefined);
    case DEHERM_RECORDING_SHAPE_NULL: return expectTag(ScriptValueTag::kNull);
    case DEHERM_RECORDING_SHAPE_BOOLEAN: return expectTag(ScriptValueTag::kBoolean);
    case DEHERM_RECORDING_SHAPE_NUMBER: return expectTag(ScriptValueTag::kNumber);
    case DEHERM_RECORDING_SHAPE_STRING:
      if (!expectTag(ScriptValueTag::kString)) return false;
      if (value.length && !value.data) { failure = "string-argument-has-null-storage"; return false; }
      return true;
    case DEHERM_RECORDING_SHAPE_HASH:
      if (!expectTag(ScriptValueTag::kHandle)) return false;
      if (value.handleKind != ScriptHandleKind::kHash) { failure = "hash-argument-handle-kind"; return false; }
      return true;
    case DEHERM_RECORDING_SHAPE_URL:
      if (!expectTag(ScriptValueTag::kHandle)) return false;
      if (value.handleKind != ScriptHandleKind::kUrl) { failure = "url-argument-handle-kind"; return false; }
      if (!value.data) { failure = "url-argument-has-no-arena-token"; return false; }
      return true;
    case DEHERM_RECORDING_SHAPE_HANDLE:
    case DEHERM_RECORDING_SHAPE_GUI_NODE:
    case DEHERM_RECORDING_SHAPE_USERDATA:
      if (!expectTag(ScriptValueTag::kHandle)) return false;
      if (value.handleKind != ScriptHandleKind::kGuiNode &&
          value.handleKind != ScriptHandleKind::kLuaUserdata &&
          value.handleKind != ScriptHandleKind::kLuaSemanticHandle) {
        failure = "retained-handle-argument-kind";
        return false;
      }
      if (value.length == 0) { failure = "retained-handle-argument-has-no-runtime-token"; return false; }
      return true;
    case DEHERM_RECORDING_SHAPE_VECTOR3:
    case DEHERM_RECORDING_SHAPE_VECTOR4:
    case DEHERM_RECORDING_SHAPE_QUATERNION:
    case DEHERM_RECORDING_SHAPE_MATRIX4:
      return expectTag(ScriptValueTag::kDefoldValue);
    case DEHERM_RECORDING_SHAPE_SEQUENCE:
    case DEHERM_RECORDING_SHAPE_RECORD:
    case DEHERM_RECORDING_SHAPE_MAP:
      if (!expectTag(ScriptValueTag::kTable)) return false;
      if (value.length && !value.data) { failure = "table-argument-has-null-storage"; return false; }
