bool Dispatch(void*, ScriptCallFrame* frame) {
  const uint32_t route = deherm_recording_find_route(frame->stableId);
  if (route >= DEHERM_RECORDING_ROUTE_COUNT) {
    std::snprintf(gLastError, sizeof(gLastError), "recording engine has no route for stable id %u",
        frame->stableId);
    ++gViolations;
    return false;
  }
  const auto& descriptor = kDehermRecordingRoutes[route];
  Observation& observation = gObservations[route][gTransport];
  observation.recorded = true;
  observation.arity = frame->argumentCount;
  observation.context = textOf(descriptor.context);
  observation.arguments.clear();
  observation.violation.clear();

  if (frame->argumentCount != descriptor.argumentCount) {
    observation.violation = "arity-mismatch";
  } else if (frame->argumentCount && !frame->arguments) {
    observation.violation = "argument-storage-is-null";
  } else {
    for (uint32_t index = 0; index < frame->argumentCount; ++index) {
      if (index) observation.arguments += " ";
      renderValue(frame->arguments[index], observation.arguments, 0);
      std::string failure;
      if (observation.violation.empty() &&
          !matches(frame->arguments[index], kDehermRecordingShapeRefs[descriptor.argumentFirst + index], failure)) {
        observation.violation = failure;
      }
    }
  }
  if (observation.violation.empty() && descriptor.resultCount) {
    if (!frame->results) observation.violation = "result-storage-is-null";
    else if (frame->resultCapacity < descriptor.resultCount) observation.violation = "result-capacity-below-contract";
  }
  if (observation.violation.empty() && (frame->stringScratchUsed || frame->tableScratchUsed)) {
    observation.violation = "frame-scratch-was-not-fresh";
  }
  if (!observation.violation.empty()) {
    ++gViolations;
    std::snprintf(gLastError, sizeof(gLastError), "recording contract violation: %s",
        observation.violation.c_str());
    return false;
  }

  Synthesizer synthesizer{frame, {}};
  for (uint32_t index = 0; index < descriptor.resultCount; ++index) {
    if (!synthesizer.value(kDehermRecordingShapeRefs[descriptor.resultFirst + index], &frame->results[index])) {
      observation.violation = synthesizer.failure;
      ++gViolations;
      std::snprintf(gLastError, sizeof(gLastError), "recording result synthesis failed: %s",
          synthesizer.failure.c_str());
      return false;
    }
  }
  frame->resultCount = descriptor.resultCount;
  return true;
}

const char* LastError(void*) { return gLastError; }

