extern "C" {

uint32_t deherm_recording_find_route(uint32_t stableId) {
  for (uint32_t index = 0; index < DEHERM_RECORDING_ROUTE_COUNT; ++index) {
    if (kDehermRecordingRoutes[index].stableId == stableId) return index;
  }
  return DEHERM_RECORDING_ROUTE_COUNT;
}

void deherm_recording_install(void) {
  gLastError[0] = '\0';
  installScriptBridgeApi({nullptr, Dispatch, LastError, Release});
}

void deherm_recording_uninstall(void) { uninstallScriptBridgeApi(); }

void deherm_recording_select_transport(uint32_t transport) {
  gTransport = transport < DEHERM_RECORDING_TRANSPORT_COUNT ? transport : 0;
}

const char* deherm_recording_observed_arguments(uint32_t route, uint32_t transport) {
  return gObservations[route][transport].arguments.c_str();
}

uint32_t deherm_recording_observed_arity(uint32_t route, uint32_t transport) {
  return gObservations[route][transport].arity;
}

const char* deherm_recording_observed_context(uint32_t route, uint32_t transport) {
  return gObservations[route][transport].context.c_str();
}

const char* deherm_recording_observed_violation(uint32_t route, uint32_t transport) {
  return gObservations[route][transport].violation.c_str();
}

uint32_t deherm_recording_violation_count(void) { return gViolations; }

void deherm_recording_record_results(
    uint32_t route, uint32_t transport, uint32_t resultCount,
    const char* specification, const char* status) {
  if (route >= DEHERM_RECORDING_ROUTE_COUNT || transport >= DEHERM_RECORDING_TRANSPORT_COUNT) return;
  Observation& observation = gObservations[route][transport];
  observation.driven = true;
  observation.resultCount = resultCount;
  observation.results = specification ? specification : "";
  observation.status = status ? status : "";
}

const char* deherm_recording_driver_results(uint32_t route, uint32_t transport) {
  return gObservations[route][transport].results.c_str();
}

uint32_t deherm_recording_driver_result_count(uint32_t route, uint32_t transport) {
  return gObservations[route][transport].resultCount;
}

const char* deherm_recording_driver_status(uint32_t route, uint32_t transport) {
  return gObservations[route][transport].status.c_str();
}

int deherm_recording_driver_present(uint32_t route, uint32_t transport) {
  return gObservations[route][transport].driven ? 1 : 0;
}

}  // extern "C"
